def run(input):
    game = json.decode(json.encode(input["game"]))
    text = input["text"]
    reset = not game or "重新开始" in text
    if reset:
        game = {"found": [], "solved": False, "attempts": 0}
    # The original case and its four independent evidence requirements.
    evidence = {
        "method_lock": "门锁和门缝有新鲜细线划痕。",
        "method_key": "壁炉暗格里有备用钥匙痕迹。",
        "time": "留声机会循环播放，死亡时间被误导。",
        "route_footprints": "后廊有湿脚印和雨水路线。",
        "route_skirt": "沈知秋裙摆有未干雨渍。",
        "motive_will": "遗嘱草稿牵涉大半遗产。",
        "motive_newspaper": "旧报纸揭示沈知秋生父与沈鹤年的旧仇。",
    }
    locations = {
        "门锁": ["method_lock"], "门缝": ["method_lock"],
        "壁炉": ["method_key"], "留声机": ["time"],
        "后廊": ["route_footprints"], "裙摆": ["route_skirt"], "询问沈知秋": ["route_skirt"],
        "沈知秋房间": ["motive_will", "motive_newspaper"],
        "抽屉": ["motive_will", "motive_newspaper"],
        "遗嘱": ["motive_will"], "旧报纸": ["motive_newspaper"],
    }
    if not game["solved"]:
        for location, clues in locations.items():
            if location in text and any([word in text for word in ["查", "搜", "看", "检查", "调查", "问"]]):
                for clue in clues:
                    if clue not in game["found"]:
                        game["found"].append(clue)
        accusing = any([word in text for word in ["指认", "凶手", "对质"]])
        if accusing:
            game["attempts"] += 1
        found = game["found"]
        missing = []
        if "method_lock" not in found or "method_key" not in found:
            missing.append("密室手法")
        if "time" not in found:
            missing.append("死亡时间")
        if "route_footprints" not in found and "route_skirt" not in found:
            missing.append("行动路线")
        if "motive_will" not in found or "motive_newspaper" not in found:
            missing.append("动机")
        if not missing and accusing and "沈知秋" in text:
            game["solved"] = True
    else:
        missing = []
    clues = [evidence[clue] for clue in game["found"] if clue in evidence]
    context = {"title": "雨夜留声机", "clues": clues, "missing": missing, "solved": game["solved"], "attempts": game["attempts"]}
    if game["solved"]:
        context["culprit"] = "沈知秋"
        context["solution"] = "备用钥匙进出书房，细线拉内门闩伪造反锁；循环留声机误导死亡时间；经后廊返回；遗嘱与生父旧仇构成动机。"
    return {"game": game, "context": json.encode(context), "feedback": "", "valid": True, "private": ""}

